script:
html { scroll-behavior: smooth; color-scheme: dark; }
::selection { background: #FF4D00; color: #101012; }
.rg-cap { opacity: 0; transform: translateY(6px); transition: opacity 0.25s ease-out, transform 0.25s ease-out; }
.rg-tile:hover .rg-cap { opacity: 1; transform: none; }
.rg-tile img { transition: transform 0.9s cubic-bezier(0.22, 1, 0.36, 1); }
.rg-tile:hover img { transform: scale(1.025); }
